        let qty = 1;

        function changeQty(delta) {
            qty = Math.max(1, Math.min(9, qty + delta));
            document.getElementById('qty').textContent = qty;
        }

        function addToCartDetail() {
            const btn = document.querySelector('.btn-add-cart');
            btn.textContent = '✓ 已加入购物袋';
            btn.style.background = '#5B8C5A';
            setTimeout(function() {
                btn.textContent = '加入购物袋';
                btn.style.background = '#2C2C2C';
            }, 2000);
        }

        function switchTab(el, tabId) {
            document.querySelectorAll('.tab-btn').forEach(function(btn) {
                btn.classList.remove('active');
            });
            el.classList.add('active');
            document.querySelectorAll('.tab-content').forEach(function(tab) {
                tab.style.display = 'none';
            });
            document.getElementById('tab-' + tabId).style.display = 'block';
        }

        // Color selection
        document.querySelectorAll('.color-option').forEach(function(opt) {
            opt.addEventListener('click', function() {
                document.querySelectorAll('.color-option').forEach(function(o) {
                    o.classList.remove('selected');
                });
                this.classList.add('selected');
            });
        });

        // Size selection
        document.querySelectorAll('.size-option').forEach(function(opt) {
            opt.addEventListener('click', function() {
                document.querySelectorAll('.size-option').forEach(function(o) {
                    o.classList.remove('selected');
                });
                this.classList.add('selected');
            });
        });

        // Thumb selection
        document.querySelectorAll('.thumb').forEach(function(thumb) {
            thumb.addEventListener('click', function() {
                document.querySelectorAll('.thumb').forEach(function(t) {
                    t.classList.remove('active');
                });
                this.classList.add('active');
            });
        });
    </script>
