        }

        .summary-row {
            display: flex;
            justify-content: space-between;
            margin-bottom: 14px;
            font-size: 14px;
        }

        .summary-row .label {
            color: #777;
        }

        .summary-row .value {
            font-weight: 500;
        }

        .summary-row.discount .value {
