        .summary-total {
            display: flex;
            justify-content: space-between;
            align-items: baseline;
            margin-bottom: 24px;
        }

        .summary-total .label {
            font-size: 16px;
            font-weight: 600;
        }

        .summary-total .value {
            font-size: 28px;
            font-weight: 700;
            color: #C75B3A;
        }

        .checkout-btn {
            width: 100%;
            padding: 16px;
            background: #2C2C2C;
            color: #fff;
            border: none;
            border-radius: 8px;
            font-size: 16px;
            cursor: pointer;
            transition: background 0.2s;
            letter-spacing: 1px;
