            color: #555;
            border: 1.5px solid #DDD5CC;
            border-radius: 8px;
            font-size: 14px;
            cursor: pointer;
            transition: all 0.2s;
            text-align: center;
        }

        .continue-btn:hover {
            border-color: #2C2C2C;
            color: #2C2C2C;
        }

        .summary-note {
            margin-top: 16px;
            font-size: 12px;
            color: #999;
            text-align: center;
            line-height: 1.8;
        }

        .summary-note .highlight {
            color: #5B8C5A;
            font-weight: 500;
        }

        /* Trust Badges */
        .trust-badges {
            display: flex;
            justify-content: center;
            gap: 24px;
            margin-top: 24px;
            padding-top: 20px;
            border-top: 1px solid #EDE8E3;
        }

        .trust-item {
            font-size: 12px;
            color: #999;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        /* Footer */
        .footer {
            background: #2C2C2C;
            color: #ccc;
            padding: 60px 40px 30px;
            margin-top: 40px;
        }

        .footer-inner {
            max-width: 1280px;
            margin: 0 auto;
            display: grid;
            grid-template-columns: 2fr 1fr 1fr 1fr;
            gap: 40px;
            margin-bottom: 40px;
        }

        .footer-brand h3 {
            font-size: 24px;
            color: #fff;
            margin-bottom: 12px;
            letter-spacing: 3px;
        }

        .footer-brand p {
            font-size: 13px;
            line-height: 1.8;
            color: #999;
        }

        .footer-col h4 {
            font-size: 14px;
            color: #fff;
            margin-bottom: 16px;
        }

        .footer-col a {
            display: block;
            font-size: 13px;
            color: #999;
            margin-bottom: 10px;
            transition: color 0.2s;
        }

        .footer-col a:hover {
            color: #fff;
        }

        .footer-bottom {
            max-width: 1280px;
            margin: 0 auto;
            padding-top: 24px;
            border-top: 1px solid #444;
            font-size: 12px;
            color: #777;
            text-align: center;
        }

        @media (max-width: 1024px) {
            .cart-container {
                grid-template-columns: 1fr;
            }
            .summary {
                position: static;
            }
            .cart-item {
                grid-template-columns: 70px 1fr;
                gap: 16px;
            }
            .item-price, .item-qty, .item-remove {
                grid-column: 2;
            }
        }

        @media (max-width: 768px) {
            .header-inner {
                padding: 0 20px;
            }
            .cart-container {
                padding: 24px 20px 60px;
            }
            .cart-item {
                grid-template-columns: 1fr;
            }
            .item-img {
                width: 100%;
                height: 120px;
            }
            .footer-inner {
                grid-template-columns: 1fr 1fr;
            }
        }
    </style>
</head>
