    <script>
        function changeItemQty(btn, delta) {
            var qtyEl = btn.parentElement.querySelector('.qty-val');
            var val = parseInt(qtyEl.textContent);
            val = Math.max(1, Math.min(9, val + delta));
            qtyEl.textContent = val;
        }

        function removeItem(el) {
            var item = el.closest('.cart-item');
            item.style.opacity = '0';
            item.style.transform = 'translateX(20px)';
            item.style.transition = 'all 0.3s';
            setTimeout(function() {
                item.remove();
            }, 300);
        }

        function applyPromo() {
            var btn = document.querySelector('.promo-btn');
            btn.textContent = '已应用';
            btn.style.background = '#5B8C5A';
            btn.style.color = '#fff';
            btn.style.borderColor = '#5B8C5A';
        }

        function checkout() {
            var btn = document.querySelector('.checkout-btn');
            btn.textContent = '正在跳转支付页面...';
            btn.style.background = '#5B8C5A';
            setTimeout(function() {
                btn.textContent = '去结算';
                btn.style.background = '#2C2C2C';
            }, 2000);
        }
    </script>
